/**
 * Main Configuration for DrinkWater Bot.
 * 
 */

const config = {
  // General settings
  removeUnconfirmedCallbacks: false,    //experimental 
  language: 'en', // supported: 'en', 'de'
  analyzeUserInput: true,
  debug: true,
  isProd: true,
  version: "v0.6.0",

  // Ollama 
  ollamaModel: "gemma3:27b",

  // Aggressive Mode
  aggressiveMode: true,
  aggressiveModeIgnoredMax: 3,  

  // Prompt History
  usePromptHistory: true,
  modelMessagesHistoryMax: 6,

  // Deadlock Protection
  deadLockMaxMainSec: 30,       // safety fallback estimated runtime of main path
  deadLockMaxSubSec: 15,        // safety fallback estimated runtime of sub path
  deadLockMaxAggroSec: 30,      // safety fallback estimated runtime of aggro path

  // Time Locks (Scheduler Nodes)
  /* these are used for time based locks */
  lockMainSec: 60,               //*60,
  lockSubSec: 15,
  lockAggressiveModeSec: 25,  

  // Weather
  weatherLocation: "Dortmund",
  temperatureHot: 26,           //*60,

  // Daily Goal ml
  dailyGoal: 2000,

  // Telegram Debugging
  sendTelegramDebugAggroMessage: false
};

return [{
  json: {
    config: config
  }
}];
